//! IANA service-name lookups for TCP and UDP ports.
//!
//! The table is generated by `tools/gen-names` from the IANA service-name
//! registry, which is dedicated to the public domain (CC0 1.0). IANA lists
//! aliases as separate rows; the generator keeps the first entry for a port
//! as the name Packetfin shows.

include!("services_data.rs");

fn lookup(table: &'static [(u16, &'static str)], port: u16) -> Option<&'static str> {
    table
        .binary_search_by_key(&port, |(key, _)| *key)
        .ok()
        .and_then(|index| table.get(index))
        .map(|(_, name)| *name)
}

/// The registered service name for a port, if the registry has one.
pub fn service_name(port: u16, tcp: bool) -> Option<&'static str> {
    lookup(if tcp { TCP_SERVICES } else { UDP_SERVICES }, port)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registered_service_names_resolve() {
        assert_eq!(service_name(80, true), Some("http"));
        assert_eq!(service_name(53, true), Some("domain"));
        assert_eq!(service_name(53, false), Some("domain"));
        assert_eq!(service_name(443, true), Some("https"));
        assert_eq!(service_name(1234, false), Some("search-agent"));
        assert_eq!(service_name(9100, false), Some("hp-pdl-datastr"));
    }

    #[test]
    fn unassigned_ports_have_no_name() {
        assert_eq!(service_name(0, true), None);
        assert_eq!(service_name(65_535, false), None);
    }

    #[test]
    fn the_tables_are_sorted_and_unique() {
        for table in [TCP_SERVICES, UDP_SERVICES] {
            assert!(table.windows(2).all(|pair| match pair {
                [left, right] => left.0 < right.0,
                _ => true,
            }));
        }
    }
}
